public class Solution {
    public static int twiceMax(int[] a) {
        // BUG: original flaw kept — the second loop re-scans from 0
        // and doubles the FIRST element instead of returning 2 * max
        int max = a[0];
        for (int x : a) {
            if (x > max) {
                max = x;
            }
        }
        for (int i = 0; i < a.length; i++) {
            if (a[i] == max) {
                return a[0] * 2;
            }
        }
        return -1;
    }
}

